    /*
     * Add to the Activities
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Lead
     */
    public Lead addToActivities( UUID parentId, Activity addTo ) {
	    LOGGER.info("handling AssignActivitiesToLeadEvent - " );
	    
	    Lead parentEntity = repository.findById(parentId).get();
	    Activity child = registry.project( Activity.class, addTo.getActivityId());
	    
	    parentEntity.getActivities().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the Activities
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	Lead
     */
	public Lead removeFromActivities( UUID parentId, Activity removeFrom ) {
	    LOGGER.info("handling RemoveActivitiesFromLeadEvent " );
	
	    Lead parentEntity = repository.findById(parentId).get();
	    Activity child = registry.project( Activity.class, removeFrom.getActivityId());
	    
	    parentEntity.getActivities().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}

